    var t = function (k) { var x = (opt[k] || OUTLINE[k]).split(": "); return "<li><b>" + esc(x[0]) + ":</b> " + esc(x.slice(1).join(": ")) + "</li>"; };
    return '<ol class="lx-rn-outline">' + t("head") + fields.filter(function (f) { return f.at === "top"; }).map(w).join("") + t("plan") + t("results")
